// Agent-01 normalization + Agent-09 integrity gates (mirror of engine/data_audit.py)
const raw = ($json && $json.data) || [];
const symbol = $('Per Symbol').item.json.symbol;
const rows = raw.map(r => ({ ts: new Date(Number(r[0])).toISOString(), open:+r[1], high:+r[2], low:+r[3], close:+r[4], volume:+r[5] }));
const bad = [];
for (const k of rows) {
  if (!(k.open>0 && k.high>0 && k.low>0 && k.close>0)) bad.push({ts:k.ts, g:'positive'});
  if (k.high < k.low) bad.push({ts:k.ts, g:'h<l'});
  if (k.close > k.high || k.close < k.low) bad.push({ts:k.ts, g:'close-range'});
  if (!(k.volume >= 0)) bad.push({ts:k.ts, g:'volume'});
}
const seen = new Set(); let dup = 0;
for (const k of rows) { if (seen.has(k.ts)) dup++; seen.add(k.ts); }
const verdict = (bad.length === 0 && dup === 0 && rows.length > 0) ? 'PASS' : 'FAIL';
return [{ json: { symbol, verdict, checked: rows.length, defects: bad.slice(0,10), duplicates: dup, rows: verdict === 'PASS' ? rows : [] } }];
